-- Keep invoice-created mail visually flat inside the global GoJet mail shell.
-- The spacing anchors below belong to the flat heading/CTA rows; they do not
-- introduce a nested card or a second bordered container.
UPDATE mail_templates
SET html_template = '<p class="muted" style="padding:0 8px 18px">账单通知</p><h1>新账单已生成</h1><p>工作区 <strong>{{workspace_name}}</strong> 已生成一张新的 {{plan_name}} 套餐账单。</p><table role="presentation" style="width:100%;border-collapse:collapse;margin:22px 0 18px"><tr><td style="padding:11px 0;border-bottom:1px solid #e7edea;color:#6b7b73">套餐</td><td style="padding:11px 0;border-bottom:1px solid #e7edea;text-align:right;font-weight:700">{{plan_name}}</td></tr><tr><td style="padding:11px 0;border-bottom:1px solid #e7edea;color:#6b7b73">服务周期</td><td style="padding:11px 0;border-bottom:1px solid #e7edea;text-align:right">{{period_days}} 天</td></tr><tr><td style="padding:11px 0;border-bottom:1px solid #e7edea;color:#6b7b73">应付金额</td><td style="padding:11px 0;border-bottom:1px solid #e7edea;text-align:right;font-size:18px;font-weight:800">{{settlement_amount}} {{settlement_currency}}</td></tr><tr><td style="padding:11px 0;color:#6b7b73">支付期限</td><td style="padding:11px 0;text-align:right">{{due_at}}</td></tr></table><p class="muted">{{fx_detail}}</p><p style="margin-top:24px;padding:18px 8px 0"><a class="button" href="{{billing_url}}">查看并支付账单</a></p>'
WHERE template_key = 'invoice_created';